        status VARCHAR(20) NOT NULL
    );

    INSERT @real_movies
        (source_ref, title, slug, synopsis, director, cast_text, duration_minutes,
         age_rating, release_date, original_language, country, poster_url, backdrop_url, trailer_url, status)
    VALUES
        ('LOTTE-12263', N'MẸ ƠI VỀ NHÀ', 'me-oi-ve-nha-12263', N'Không còn là những mảnh ghép riêng lẻ, sự xuất hiện của mỗi người đều ẩn chứa một bí mật. Huy Hoàng tìm kiếm gì ở nơi mình chưa từng thuộc về? Và vì sao sự xuất hiện của hai cô gái Việt Nam lại khiến cuộc đời của Huy Hoàng thay đổi toàn bộ.

Liệu sự đồng hành của bộ tứ Lee Yi-Kyung, Hoàng Yến Chibi, Choi Daniel và Minh Hà có thể tháo gỡ được "nút thắt" của định mệnh? Mọi câu trả lời sẽ sớm được giải mã tại rạp.', N'To be announced', N'To be announced', 98, 'T16', CONVERT(DATE, '2026-07-10', 23), N'Vietnamese', N'Vietnam', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12263_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12263_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12263_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12206', N'QUỶ BẮT HỒN', 'quy-bat-hon-12206', N'Lớp kem trắng bị nhuộm đỏ. Những bông hoa úa, như thứ gì đó đã chết từ trước. Đôi bàn tay đen đặc, giữ chặt chiếc bánh như một nghi lễ… hơn là một buổi tiệc. Một sinh nhật, hay một ngày được định sẵn để bị lấy đi? Và phía sau, thứ đó đã từng là con người. Hay vốn đó chưa từng là người? Đúng tháng đúng ngày, hồn về theo quỷ.', N'To be announced', N'To be announced', 103, 'T16', CONVERT(DATE, '2026-07-10', 23), N'Vietnamese', N'Vietnam', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202607/12206_103_100004.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202607/12206_103_100004.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12206_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12257', N'BANG DREAM ITS MYGO PART 2: GIAI ĐIỆU CỦA CHÚNG TA', 'bang-dream-its-mygo-part-2-giai-dieu-cua-chung-ta-12257', N'Khi các thành viên dần hội tụ dưới cái tên MyGO!!!!!, những vết thương từ quá khứ vẫn chưa hoàn toàn khép lại. Những mâu thuẫn, lựa chọn và cảm xúc chưa thể gọi thành lời tiếp tục thử thách mối liên kết mong manh giữa họ. Liệu năm cô gái có thể tìm thấy nơi mình thuộc về và cất lên giai điệu thực sự của riêng mình?', N'To be announced', N'To be announced', 120, 'P', CONVERT(DATE, '2026-07-10', 23), N'Vietnamese', N'Japan', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12257_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12257_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202607/12257_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12103', N'MINIONS & QUÁI VẬT', 'minions-quai-vat-12103', N'Minions & Quái Vật là câu chuyện vừa náo loạn, vừa ngớ ngẩn nhưng “hoàn toàn có thật” về cách Minions chinh phục Hollywood, trở thành ngôi sao điện ảnh, rồi mất tất cả, vô tình thả quái vật ra khắp thế giới và sau đó phải cùng nhau hợp sức để cứu lấy hành tinh khỏi chính mớ hỗn loạn mà mình tạo ra.', N'To be announced', N'To be announced', 90, 'P', CONVERT(DATE, '2026-07-01', 23), N'Vietnamese', N'USA', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12103_103_100004.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12103_103_100004.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202602/12103_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12139', N'MOANA (Live Action)', 'moana-live-action-12139', N'Nữ anh hùng biển cả quay trở lại. Moana từ Disney sẽ khơi dậy một làn sóng mới, để sự dũng cảm, lòng vị tha và âm nhạc hòa chung một nhịp chảy.', N'To be announced', N'To be announced', 120, 'K', CONVERT(DATE, '2026-07-10', 23), N'Vietnamese', N'USA', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202603/12139_103_100002.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202603/12139_103_100002.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12139_301_100002.mp4', 'NOW_SHOWING'),
        ('LOTTE-12238', N'BẦY XÁC SỐNG', 'bay-xac-song-12238', N'Siêu phẩm zombie từ Đạo diễn đã tạo nên huyền thoại Train to Busan. Khi một dịch bệnh bí ẩn bùng phát tại tòa cao ốc giữa trung tâm Seoul, những người sống sót bị mắc kẹt và buộc phải chiến đấu để thoát thân. Những người đã nhiễm bệnh không chỉ là những xác sống mất não thông thường - chúng đang tiến hóa và săn mồi theo bầy đàn có tổ chức. Hy vọng duy nhất của những người sống sót phụ thuộc vào một gã đàn ông tự nhận đang mang trong mình loại vắc-xin có thể chấm dứt đại dịch. Trong cuộc chạy trốn nghẹt thở lên sân thượng, ranh giới giữa con người và quái vật dần sụp đổ.', N'To be announced', N'To be announced', 117, 'T16', CONVERT(DATE, '2026-06-12', 23), N'Vietnamese', N'Vietnam', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12238_103_100003.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12238_103_100003.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202605/12238_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12246', N'ÁM ẢNH', 'am-anh-12246', N'Bear, một chàng trai si tình, đã bẻ gãy món đồ chơi bí ẩn mang tên "Liễu Ước Nguyện" để đổi lấy tình yêu của cô gái mình thầm thương. Điều ước nhanh chóng trở thành hiện thực, nhưng hạnh phúc mà anh hằng mong đợi lại dần biến thành cơn ác mộng. Bear dần nhận ra một sự thật rùng rợn: cái giá phải trả cho món quà kỳ diệu đó kinh hoàng và đen tối hơn bất cứ điều gì anh có thể tưởng tượng.', N'To be announced', N'To be announced', 108, 'T18', CONVERT(DATE, '2026-06-19', 23), N'Vietnamese', N'USA', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12246_103_100002.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12246_103_100002.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12246_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12264', N'MA NỮ OÁN TÌNH', 'ma-nu-oan-tinh-12264', N'Mang theo những ám ảnh từ quá khứ, Malee - do Engfa thủ vai, trở về khu căn hộ gắn liền với tuổi thơ và tìm thấy tình yêu bên Pran – một nhà thực vật học đam mê nghệ thuật pha trà. Thế nhưng, sự xuất hiện của những mối quan hệ xung quanh Pran cùng những bí mật tưởng đã bị chôn vùi từ lâu dần làm xáo trộn mọi thứ. Khi một cái chết bất ngờ xảy ra, những sự thật đen tối dần dần được phơi bày.', N'To be announced', N'To be announced', 97, 'T18', CONVERT(DATE, '2026-07-10', 23), N'Vietnamese', N'Thailand', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12264_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202606/12264_103_100001.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12264_301_100001.mp4', 'NOW_SHOWING'),
        ('LOTTE-12183', N'LẦU CHÚ HỎA', 'lau-chu-hoa-12183', N'Lầu Chú Hỏa theo chân một nhóm streamer trẻ đột nhập vào căn biệt thự bỏ hoang gắn với truyền thuyết “con ma nhà họ Hứa”. Sự xâm phạm vào “vùng đất cấm” của họ đã vô tình đánh thức ác linh bị trấn yểm suốt hơn 100 năm. Với phong cách found footage tạo cảm giác như đang xem lại đoạn băng cuối cùng của nạn nhân, bộ phim hứa hẹn biến mỗi góc tối trong căn nhà cổ thành chuỗi bi kịch kinh hoàng và đẫm máu nhất mùa hè năm nay.', N'To be announced', N'To be announced', 94, 'T18', CONVERT(DATE, '2026-06-12', 23), N'Vietnamese', N'Vietnam', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202605/12183_103_100003.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202605/12183_103_100003.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202606/12183_301_100002.mp4', 'NOW_SHOWING'),
        ('LOTTE-12138', N'PHIM ĐIỆN ẢNH DORAEMON: NOBITA VÀ LÂU ĐÀI DƯỚI ĐÁY BIỂN PHIÊN BẢN MỚI', 'phim-dien-anh-doraemon-nobita-va-lau-dai-duoi-day-bien-phien-ban-moi-12138', N'Bước vào kì nghỉ hè, Nobita và các bạn tranh cãi chí chóe về địa điểm cắm trại. Theo đề xuất của Doraemon, cả nhóm quyết định cắm trại giữa lòng đại dương! Sử dụng bảo bối thần kì “xe Buggy chạy dưới nước” và “đèn pin thích nghi”, 5 bạn nhỏ tận hưởng chuyến cắm trại dưới đáy biển, gặp gỡ vô vàn sinh vật lí thú trên đường đi. Sau khi phát hiện một chiếc tàu đắm, nhóm bạn đã gặp chàng thanh niên bí ẩn El. Thật bất ngờ, anh ta lại là cư dân đáy biển, sống tại “liên bang Mu”, một vùng biển rộng lớn! Vốn căm ghét người mặt đất, cư dân đáy biển không thể nào tin tưởng Nobita và các bạn. Đúng lúc đó, lời thông báo “lâu đài quỷ... đã bắt đầu phục sinh!!” được truyền tới. “Lâu đài quỷ” khiến cư dân đáy biển khiếp sợ, rốt cuộc là gì? Đặt trọn niềm tin vào bè bạn trong lồng ngực, chuyến phiêu lưu vĩ đại quyết định số phận của trái đất, bắt đầu!', N'To be announced', N'To be announced', 100, 'P', CONVERT(DATE, '2026-05-22', 23), N'Vietnamese', N'Japan', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202605/12138_103_100006.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieImg/202605/12138_103_100006.jpg', N'https://media.lottecinemavn.com/Media/MovieFile/MovieMedia/202605/12138_301_100002.mp4', 'NOW_SHOWING'),
        ('LOTTE-12268', N'NGÀY XỬA NGÀY XƯA 36- HẬU DUỆ THẦN MẶT TRỜI', 'ngay-xua-ngay-xua-36-hau-due-than-mat-troi-12268', N'Kịch bản “NXNX36 – Hậu Duệ Thần Mặt Trời” là một vở kịch thần thoại Hàn Quốc được Việt hóa theo phong cách hài hước, ý nghĩa. Câu chuyện kể về cuộc chiến giữa loài người và yêu tinh Dokkaebi, cùng hành trình lập quốc của hậu duệ Thần Mặt Trời. Thiên Tôn – con của Thiên Đế – vì cảm thương loài người, đã chấp nhận giáng trần, kết duyên với Thiên Nữ (tiền kiếp là Gấu Lưu Ly), sinh ra Đàn Quân – người mang thiên mệnh trở thành vua đầu tiên của xứ sở Đàn Hương. Trong suốt thời gian nuôi dưỡng Đàn Quân, mẹ con họ phải đổi tên và sống ẩn danh để tránh sự truy lùng của yêu tinh. Vở kịch lồng ghép yếu tố giáo dục, giá trị gia đình, bảo vệ môi trường và sự lựa chọn giữa cái thiện – cái ác, cùng những màn hài duyên dáng, ca múa đặc sắc.

