        ('LOTTE-DEMO-12257-S3', 'LOTTE-12257', 'cinebook-han-river', N'Hall 1', 2, 11, 0, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12103-S3', 'LOTTE-12103', 'cinebook-ninh-kieu', N'Hall 1', 2, 11, 45, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12139-S3', 'LOTTE-12139', 'cinebook-landmark-81', N'IMAX 1', 2, 13, 0, 'IMAX', CONVERT(DECIMAL(19,2), 190000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12238-S3', 'LOTTE-12238', 'cinebook-metropolis-hanoi', N'Premium 2', 2, 14, 15, '2D', CONVERT(DECIMAL(19,2), 140000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12246-S3', 'LOTTE-12246', 'cinebook-landmark-81', N'Hall 1', 2, 16, 0, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12264-S3', 'LOTTE-12264', 'cinebook-metropolis-hanoi', N'Hall 1', 2, 17, 30, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12183-S3', 'LOTTE-12183', 'cinebook-han-river', N'Hall 1', 2, 19, 30, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English'),
        ('LOTTE-DEMO-12138-S3', 'LOTTE-12138', 'cinebook-ninh-kieu', N'Hall 1', 2, 21, 0, '2D', CONVERT(DECIMAL(19,2), 120000), N'Vietnamese', N'English');

    UPDATE dbo.showtimes
       SET status = 'CANCELLED',
           updated_at = @now
     WHERE source_ref LIKE 'LOTTE-DEMO-%'
       AND status = 'SCHEDULED'
       AND NOT EXISTS (SELECT 1 FROM @showtime_seed source WHERE source.source_ref = dbo.showtimes.source_ref);

    ;WITH desired_showtimes AS
    (
        SELECT source.source_ref,
               m.movie_id,
               a.auditorium_id,
               schedule.starts_at,
               DATEADD(MINUTE, COALESCE(m.duration_minutes, 100), schedule.starts_at) AS ends_at,
               DATEADD(DAY, -30, schedule.starts_at) AS sales_open_at,
               source.format,
               source.base_price,
               source.audio_language,
               source.subtitle_language
          FROM @showtime_seed source
          JOIN dbo.movies m ON m.source_ref = source.movie_source_ref
          JOIN dbo.cinemas c ON c.slug = source.cinema_slug
          JOIN dbo.auditoriums a ON a.cinema_id = c.cinema_id AND a.name = source.auditorium_name
         CROSS APPLY
               (
                   VALUES
                   (
                       DATEADD(MINUTE, source.local_minute,
                           DATEADD(HOUR, source.local_hour,
                               DATEADD(DAY, source.local_day_offset, @next_local_midnight_utc)))
                   )
               ) schedule(starts_at)
         WHERE NOT EXISTS
               (
                   SELECT 1 FROM dbo.showtimes conflict
                    WHERE conflict.auditorium_id = a.auditorium_id
                      AND conflict.starts_at = schedule.starts_at
                      AND (conflict.source_ref IS NULL OR conflict.source_ref <> source.source_ref)
               )
    )
    MERGE dbo.showtimes AS target
    USING desired_showtimes AS source
       ON target.source_ref = source.source_ref
    WHEN MATCHED THEN
        UPDATE SET
            movie_id = source.movie_id,
            auditorium_id = source.auditorium_id,
            starts_at = source.starts_at,
            ends_at = source.ends_at,
            sales_open_at = source.sales_open_at,
            format = source.format,
            base_price = source.base_price,
            audio_language = source.audio_language,
            subtitle_language = source.subtitle_language,
            status = 'SCHEDULED',
            updated_at = @now
    WHEN NOT MATCHED THEN
        INSERT
        (
            movie_id, auditorium_id, starts_at, ends_at, sales_open_at,
            format, base_price, audio_language, subtitle_language, status, source_ref
        )
        VALUES
        (
            source.movie_id, source.auditorium_id, source.starts_at, source.ends_at,
            source.sales_open_at, source.format, source.base_price, source.audio_language,
            source.subtitle_language, 'SCHEDULED', source.source_ref
        );

    MERGE dbo.seat_prices AS target
    USING
    (
        SELECT st.showtime_id,
               seat_type.seed_type AS seat_type,
               CASE seat_type.seed_type
                   WHEN 'STANDARD' THEN st.base_price
                   WHEN 'VIP' THEN st.base_price + 40000
                   WHEN 'COUPLE' THEN (st.base_price * 2) + 50000
               END AS price,
               CASE WHEN seat_type.seed_type = 'COUPLE' THEN 'PER_PAIR' ELSE 'PER_SEAT' END AS price_mode
          FROM dbo.showtimes st
          JOIN @showtime_seed source ON source.source_ref = st.source_ref
         CROSS JOIN (VALUES ('STANDARD'), ('VIP'), ('COUPLE')) seat_type(seed_type)
    ) AS source
       ON target.showtime_id = source.showtime_id
      AND target.seat_type = source.seat_type
    WHEN MATCHED THEN
        UPDATE SET price = source.price,
                   price_mode = source.price_mode,
                   updated_at = @now
    WHEN NOT MATCHED THEN
        INSERT (showtime_id, seat_type, price, price_mode)
        VALUES (source.showtime_id, source.seat_type, source.price, source.price_mode);

    DECLARE @admin_id BIGINT =
        (SELECT user_id FROM dbo.users WHERE email = N'admin@cinebook.vn');

    DECLARE @banner_seed TABLE
    (
        movie_source_ref VARCHAR(80) NOT NULL PRIMARY KEY,
        placement VARCHAR(30) NOT NULL,
        display_order INT NOT NULL
    );

    INSERT @banner_seed (movie_source_ref, placement, display_order)
    VALUES
        ('LOTTE-12263', 'HOME_HERO', 10),
        ('LOTTE-12206', 'HOME_HERO', 20),
        ('LOTTE-12257', 'HOME_HERO', 30),
        ('LOTTE-12103', 'HOME_PROMO', 40),
        ('LOTTE-12139', 'HOME_PROMO', 50);

    UPDATE b
       SET is_active = 0,
           updated_at = @now
      FROM dbo.banners b
     WHERE b.placement IN ('HOME_HERO', 'HOME_PROMO')
       AND (b.target_url LIKE N'/movies/%'
            OR b.title IN (N'Experience Orbit Zero in IMAX', N'Welcome Offer: 10% Off'))
       AND NOT EXISTS
           (
               SELECT 1
                 FROM @banner_seed seed
                 JOIN dbo.movies m ON m.source_ref = seed.movie_source_ref
                WHERE b.target_url = N'/movies/' + CAST(m.movie_id AS NVARCHAR(20))
                  AND b.placement = seed.placement
           );

    MERGE dbo.banners AS target
    USING
    (
        SELECT seed.placement,
               seed.display_order,
               m.title,
               LEFT(m.synopsis, 160) AS subtitle,
               COALESCE(m.backdrop_url, m.poster_url) AS image_url,
               N'/movies/' + CAST(m.movie_id AS NVARCHAR(20)) AS target_url,
               DATEADD(DAY, -7, @now) AS starts_at,
               DATEADD(DAY, 120, @now) AS ends_at
          FROM @banner_seed seed
          JOIN dbo.movies m ON m.source_ref = seed.movie_source_ref
    ) AS source
       ON target.target_url = source.target_url
      AND target.placement = source.placement
    WHEN MATCHED THEN
        UPDATE SET title = source.title,
                   subtitle = source.subtitle,
                   image_url = source.image_url,
                   display_order = source.display_order,
                   starts_at = source.starts_at,
                   ends_at = source.ends_at,
                   is_active = 1,
                   updated_at = @now
    WHEN NOT MATCHED THEN
        INSERT
        (
            title, subtitle, image_url, target_url, placement,
            display_order, starts_at, ends_at, created_by
        )
        VALUES
        (
            source.title, source.subtitle, source.image_url, source.target_url, source.placement,
            source.display_order, source.starts_at, source.ends_at, @admin_id
        );

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
